-- LEGACY SOURCE: upgrade_admin_alert_inventory_edits.sql
-- Run after upgrade_membership_collaboration.sql and
-- upgrade_inventory_finance_approvals.sql in the Supabase SQL Editor.
-- Safe to rerun. A quantity edit remains an append-only stock movement.

begin;

-- Announcements are the club alerts published by an administrator.
-- Members retain read access; only an approved administrator can delete one.
grant delete on public.announcements to authenticated;
drop policy if exists "Admins delete announcements" on public.announcements;
create policy "Admins delete announcements" on public.announcements
  for delete to authenticated using ((select public.is_admin()));

-- Keep an administrator action record even after the alert disappears.
create or replace function public.log_deleted_announcement()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.audit_events(actor_id,action,target_type,target_id)
    values (auth.uid(),'announcement_deleted','announcement',old.id);
  return old;
end $$;
revoke all on function public.log_deleted_announcement() from public,anon,authenticated;
drop trigger if exists announcement_deleted_audit on public.announcements;
create trigger announcement_deleted_audit after delete on public.announcements
  for each row execute function public.log_deleted_announcement();

-- Set the in-stock quantity using an audited adjustment. The expected values
-- protect a form opened before another checkout or stock change occurred.
-- Checked-out stock remains unchanged: total and available move together.
create or replace function public.set_inventory_available_quantity(
  p_item uuid,
  p_target_available integer,
  p_expected_total integer,
  p_expected_available integer,
  p_note text
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_total integer;
  v_available integer;
  v_checked_out bigint;
  v_delta bigint;
  v_note text := trim(p_note);
begin
  if not public.is_admin() then
    raise exception 'Administrator access required';
  end if;
  if p_item is null or p_target_available is null or p_target_available < 0
      or p_expected_total is null or p_expected_total < 0
      or p_expected_available is null or p_expected_available < 0 then
    raise exception 'Enter valid inventory quantities';
  end if;
  if v_note is null or char_length(v_note) not between 1 and 2000 then
    raise exception 'Enter a reason for this quantity change';
  end if;

  select quantity_total,quantity_available into v_total,v_available
    from public.inventory_items where id = p_item for update;
  if not found then
    raise exception 'Inventory item not found';
  end if;
  if v_total is distinct from p_expected_total
      or v_available is distinct from p_expected_available then
    raise exception 'Stock changed since you opened this form. Refresh and try again';
  end if;
  if p_target_available = v_available then
    raise exception 'Enter a different in-stock quantity';
  end if;

  v_checked_out := v_total::bigint - v_available::bigint;
  if p_target_available::bigint + v_checked_out > 2147483647 then
    raise exception 'Total stock would exceed the maximum allowed quantity';
  end if;
  v_delta := p_target_available::bigint - v_available::bigint;

  -- The existing admin-only RPC updates both counts and writes a permanent
  -- movement in this same transaction, while this row remains locked.
  return public.record_inventory_movement(
    p_item,
    case when v_delta > 0 then 'add_stock' else 'remove_stock' end,
    abs(v_delta)::integer,
    null,
    v_note
  );
end $$;
revoke all on function public.set_inventory_available_quantity(uuid,integer,integer,integer,text)
  from public,anon,authenticated;
grant execute on function public.set_inventory_available_quantity(uuid,integer,integer,integer,text)
  to authenticated;

commit;

-- LEGACY SOURCE: upgrade_inventory_unit_changes.sql
-- Run after upgrade_inventory_finance_approvals.sql and
-- upgrade_admin_alert_inventory_edits.sql in the Supabase SQL Editor.
-- Existing movement quantities retain their original meaning when an
-- administrator changes an item's measurement unit. Safe to rerun.

begin;

-- Historical stock movements could not have been made in a previous unit:
-- update_inventory_item_catalog blocked unit changes as soon as an item had
-- stock or movement history. Capture that original unit once, before the
-- first conversion. Unit changes for empty items with no stock movements
-- could already exist as zero-quantity update_details rows; their old unit
-- is captured directly from old_details instead.
alter table public.inventory_movements
  add column if not exists unit_at_movement text;

-- If the protection above was bypassed in an older installation, we cannot
-- infer an unsnapshotted quantity's historical unit. Stop instead of
-- silently labelling that quantity with today's unit.
do $$
begin
  if exists (
    select 1
      from public.inventory_movements changed
      join public.inventory_movements stock
        on stock.item_id = changed.item_id
       and stock.created_at <= changed.created_at
       and stock.quantity > 0
       and stock.unit_at_movement is null
     where changed.kind = 'update_details'
       and changed.old_details ? 'unit'
       and changed.new_details ? 'unit'
       and changed.old_details->>'unit' is distinct from changed.new_details->>'unit'
  ) then
    raise exception 'Cannot safely label historical stock units. Review older unit changes before running this migration';
  end if;
end $$;

-- The existing immutable trigger protects all historic ledger fields. Disable
-- only that trigger, inside this transaction and while ALTER TABLE holds its
-- table lock, to fill this new snapshot field; immediately re-enable it.
alter table public.inventory_movements disable trigger inventory_movement_immutable;
update public.inventory_movements m
   set unit_at_movement = case
     when m.kind = 'update_details'
       then coalesce(nullif(trim(m.old_details->>'unit'),''), i.unit)
     else i.unit
   end
  from public.inventory_items i
 where i.id = m.item_id
   and m.unit_at_movement is null;
alter table public.inventory_movements enable trigger inventory_movement_immutable;

alter table public.inventory_movements
  alter column unit_at_movement set not null;
alter table public.inventory_movements
  drop constraint if exists inventory_movement_unit_snapshot_check;
alter table public.inventory_movements
  add constraint inventory_movement_unit_snapshot_check
    check (char_length(trim(unit_at_movement)) between 1 and 30);

-- A regular movement snapshots the item's current unit. A catalog edit
-- snapshots the unit before that edit, which is stored in old_details.
-- In particular, the new unit-change RPC updates the item and then inserts
-- an update_details entry, so its historical snapshot remains the old unit.
create or replace function public.set_inventory_movement_unit()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_unit text;
begin
  select unit into v_unit
    from public.inventory_items where id = new.item_id;
  if not found then
    raise exception 'Inventory item not found';
  end if;
  new.unit_at_movement := case
    when new.kind = 'update_details'
      then coalesce(nullif(trim(new.old_details->>'unit'),''),v_unit)
    else v_unit
  end;
  return new;
end $$;
revoke all on function public.set_inventory_movement_unit()
  from public,anon,authenticated;
drop trigger if exists inventory_movement_unit_snapshot on public.inventory_movements;
create trigger inventory_movement_unit_snapshot
  before insert on public.inventory_movements
  for each row execute function public.set_inventory_movement_unit();

-- Unit conversion is an explicit physical recount, not a silent relabel.
-- No outstanding loans may cross the boundary: the existing return RPC
-- compares checkout and return quantities as integers for the same member.
-- Both counts and the reorder level switch atomically, with old/new values
-- and the administrator's reason in the append-only movement history.
create or replace function public.change_inventory_unit(
  p_item uuid,
  p_new_unit text,
  p_new_quantity integer,
  p_new_reorder_level integer,
  p_expected_unit text,
  p_expected_total integer,
  p_expected_available integer,
  p_expected_reorder_level integer,
  p_note text
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_old public.inventory_items%rowtype;
  v_unit text := trim(p_new_unit);
  v_note text := trim(p_note);
  v_old_details jsonb;
  v_new_details jsonb;
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Administrator access required';
  end if;
  if v_unit is null or char_length(v_unit) not between 1 and 30 then
    raise exception 'Enter a measurement unit between 1 and 30 characters';
  end if;
  if p_new_quantity is null or p_new_quantity < 0
     or p_new_reorder_level is null or p_new_reorder_level < 0 then
    raise exception 'Enter a valid whole-number quantity and reorder level';
  end if;
  if v_note is null or char_length(v_note) not between 1 and 2000 then
    raise exception 'Enter a reason for this unit change and recount';
  end if;

  select * into v_old
    from public.inventory_items where id = p_item for update;
  if not found then
    raise exception 'Inventory item not found';
  end if;
  if v_old.unit is distinct from p_expected_unit
     or v_old.quantity_total is distinct from p_expected_total
     or v_old.quantity_available is distinct from p_expected_available
     or v_old.reorder_level is distinct from p_expected_reorder_level then
    raise exception 'Inventory changed since you opened this form. Refresh and try again';
  end if;
  if v_unit = v_old.unit then
    raise exception 'Enter a different measurement unit';
  end if;
  if v_old.quantity_total <> v_old.quantity_available or exists (
    select 1 from public.inventory_movements
      where item_id = p_item and kind in ('check_out','return')
      group by member_id
      having sum(case when kind = 'check_out' then quantity else -quantity end) <> 0
  ) then
    raise exception 'Return all checked-out stock before changing its unit';
  end if;

  v_old_details := jsonb_build_object(
    'name',v_old.name,'category',v_old.category,'item_type',v_old.item_type,
    'unit',v_old.unit,'reorder_level',v_old.reorder_level,
    'quantity_total',v_old.quantity_total,'quantity_available',v_old.quantity_available,
    'condition',v_old.condition,'location',v_old.location,
    'serial_number',v_old.serial_number
  );
  v_new_details := jsonb_build_object(
    'name',v_old.name,'category',v_old.category,'item_type',v_old.item_type,
    'unit',v_unit,'reorder_level',p_new_reorder_level,
    'quantity_total',p_new_quantity,'quantity_available',p_new_quantity,
    'condition',v_old.condition,'location',v_old.location,
    'serial_number',v_old.serial_number
  );

  update public.inventory_items set
    unit = v_unit, quantity_total = p_new_quantity,
    quantity_available = p_new_quantity,
    reorder_level = p_new_reorder_level, updated_at = now()
    where id = p_item;
  insert into public.inventory_movements
    (item_id,kind,quantity,member_id,note,old_details,new_details,handled_by)
    values (p_item,'update_details',0,null,v_note,v_old_details,v_new_details,auth.uid())
    returning id into v_id;
  return v_id;
end $$;
revoke all on function public.change_inventory_unit(
  uuid,text,integer,integer,text,integer,integer,integer,text)
  from public,anon,authenticated;
grant execute on function public.change_inventory_unit(
  uuid,text,integer,integer,text,integer,integer,integer,text)
  to authenticated;

notify pgrst, 'reload schema';
commit;

-- LEGACY SOURCE: upgrade_approval_emails.sql
-- Run after upgrade_roles_investors.sql in the Supabase SQL Editor.
-- Queue one welcome email when an account first becomes approved. The delivery
-- worker uses a service-role client; no mail credential or service key belongs
-- in this migration or in the browser.

create table if not exists public.approval_email_outbox (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references public.profiles(id) on delete cascade,
  recipient_email text not null check (char_length(recipient_email) between 3 and 320),
  applicant_name text not null,
  application_type text not null check (application_type in ('member','teacher','founder','investor')),
  approved_at timestamptz not null default now(),
  status text not null default 'pending'
    check (status in ('pending','processing','retry','sent','failed')),
  attempts integer not null default 0 check (attempts between 0 and 8),
  next_attempt_at timestamptz not null default now(),
  locked_at timestamptz,
  claim_token uuid,
  sent_at timestamptz,
  provider_message_id text,
  last_error text,
  created_at timestamptz not null default now()
);
create index if not exists approval_email_due_idx
  on public.approval_email_outbox(next_attempt_at,created_at)
  where status in ('pending','retry');
create index if not exists approval_email_stale_idx
  on public.approval_email_outbox(locked_at)
  where status='processing';

alter table public.approval_email_outbox enable row level security;
revoke all on public.approval_email_outbox from public,anon,authenticated;
grant select on public.approval_email_outbox to service_role;
-- No client-facing policy: only the service-role worker and security-definer
-- trigger/function owner may read or change these email addresses and jobs.

-- Keep a separate registry so accounts already approved before this migration
-- do not receive an inaccurate first-time email after being suspended and
-- reapproved. A suspended account needs an approval audit event to prove it
-- was approved previously; suspension alone does not prove that.
create table if not exists public.approval_email_history (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  source text not null check (source in ('preexisting','email_queued')),
  tracked_at timestamptz not null default now()
);
alter table public.approval_email_history enable row level security;
revoke all on public.approval_email_history from public,anon,authenticated;
insert into public.approval_email_history(user_id,source)
select p.id,'preexisting'
  from public.profiles p
 where p.membership_status='approved'
    or exists (
      select 1 from public.audit_events a
       where a.target_type='profile' and a.target_id=p.id
         and a.action ~ '^membership_approved($|_)'
    )
on conflict (user_id) do nothing;
-- Earlier versions marked every suspended account as a prior approval. On a
-- rerun, remove that assumption where no approval audit or queued email can
-- confirm it; otherwise a first-time suspended applicant could skip the form.
delete from public.approval_email_history h using public.profiles p
 where p.id=h.user_id and h.source='preexisting'
   and p.membership_status<>'approved'
   and not exists (
     select 1 from public.audit_events a
      where a.target_type='profile' and a.target_id=p.id
        and a.action ~ '^membership_approved($|_)'
   )
   and not exists (select 1 from public.approval_email_outbox q where q.user_id=p.id);

create or replace function public.queue_approval_email()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_email text;
begin
  if new.membership_status = 'approved'
     and old.membership_status is distinct from 'approved'
     and new.role in ('member','teacher','founder','investor')
     and not exists(select 1 from public.approval_email_history h where h.user_id=new.id) then
    select lower(trim(u.email)) into v_email from auth.users u where u.id=new.id;
    if v_email is null or v_email='' then
      raise exception 'An email address is required before approving membership';
    end if;
    insert into public.approval_email_outbox
      (user_id,recipient_email,applicant_name,application_type,approved_at)
    values
      (new.id,v_email,coalesce(nullif(trim(new.full_name),''),'Club member'),
       new.role,now())
    on conflict (user_id) do nothing;
    insert into public.approval_email_history(user_id,source)
      values(new.id,'email_queued') on conflict (user_id) do nothing;
  end if;
  return new;
end $$;
revoke all on function public.queue_approval_email() from public,anon,authenticated;
drop trigger if exists queue_approval_email_on_approval on public.profiles;
create trigger queue_approval_email_on_approval
after update of membership_status on public.profiles
for each row execute function public.queue_approval_email();

-- Protect the status transition itself, including manual administrator SQL and
-- future approval paths that do not call review_membership(). An old approved
-- account being restored may have no historical application reason, but still
-- needs a confirmed email.
create or replace function public.require_complete_application_for_approval()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.membership_status = 'approved'
     and old.membership_status is distinct from 'approved'
     and new.role in ('member','teacher','founder','investor') then
    if not exists (select 1 from auth.users u
                    where u.id = new.id and u.email_confirmed_at is not null) then
      raise exception 'Applicant must verify their email before approval';
    end if;
    if nullif(trim(new.application_reason),'') is null
       and not exists (select 1 from public.approval_email_history h
                        where h.user_id = new.id) then
      raise exception 'Applicant must submit a reason for joining before approval';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.require_complete_application_for_approval()
  from public,anon,authenticated;
drop trigger if exists require_complete_application_before_approval on public.profiles;
create trigger require_complete_application_before_approval
before update of membership_status on public.profiles
for each row execute function public.require_complete_application_for_approval();

-- The application review page can report verification without exposing
-- auth.users or email addresses to browser clients. Limit each call to the
-- current page of applicants.
create or replace function public.application_verification_status(p_users uuid[])
returns table(user_id uuid,email_verified boolean,previously_approved boolean)
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if cardinality(coalesce(p_users,array[]::uuid[]))>50 then
    raise exception 'Review up to 50 applicants at a time';
  end if;
  return query
    select p.id,u.email_confirmed_at is not null,
           exists(select 1 from public.approval_email_history h where h.user_id=p.id)
      from public.profiles p
      join auth.users u on u.id=p.id
     where p.id=any(coalesce(p_users,array[]::uuid[]));
end $$;
revoke all on function public.application_verification_status(uuid[]) from public,anon;
grant execute on function public.application_verification_status(uuid[]) to authenticated;

-- Approval can only complete after email verification and an application has
-- been submitted. Restoring an existing suspended member is still possible
-- when a historical application reason was not captured.
create or replace function public.review_membership(p_user uuid,p_status text)
returns void language plpgsql security definer set search_path = '' as $$
declare v_type text;v_status text;v_reason text;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_status not in ('approved','rejected','suspended') then
    raise exception 'Invalid review decision';
  end if;
  if p_user=auth.uid() then raise exception 'You cannot review your own account'; end if;

  select p.application_type,p.membership_status,p.application_reason
    into v_type,v_status,v_reason
    from public.profiles p where p.id=p_user and p.role<>'admin' for update;
  if not found then raise exception 'Applicant not found or cannot be changed'; end if;

  if p_status='approved' then
    if not exists(select 1 from auth.users u
                   where u.id=p_user and u.email_confirmed_at is not null) then
      raise exception 'Applicant must verify their email before approval';
    end if;
    if v_status in ('pending','rejected')
       and nullif(trim(v_reason),'') is null
       and not exists(select 1 from public.approval_email_history h where h.user_id=p_user) then
      raise exception 'Applicant must submit a reason for joining before approval';
    end if;
    update public.profiles set membership_status='approved',role=v_type where id=p_user;
  else
    update public.profiles set membership_status=p_status where id=p_user;
  end if;

  insert into public.audit_events(actor_id,action,target_type,target_id)
    values(auth.uid(),'membership_'||p_status||'_'||v_type,'profile',p_user);
  if p_status='approved' then
    insert into public.notifications(user_id,kind,title,target_type,target_id)
      values(p_user,'membership','Your SPACE application was approved','application',p_user);
  end if;
end $$;
revoke all on function public.review_membership(uuid,text) from public,anon;
grant execute on function public.review_membership(uuid,text) to authenticated;

-- Safely claim due jobs without allowing two workers to send the same claim.
-- A crashed worker's claim expires after ten minutes. The provider may still
-- have accepted a message before a crash, so delivery is at least once.
create or replace function public.claim_approval_email_jobs(p_limit integer default 10)
returns setof public.approval_email_outbox
language plpgsql security definer set search_path = '' as $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required';
  end if;

  update public.approval_email_outbox j
     set status='failed',locked_at=null,claim_token=null,
         last_error=coalesce(j.last_error,'Delivery worker timed out after eight attempts')
   where j.status='processing' and j.attempts>=8
     and j.locked_at < now()-interval '10 minutes';

  return query
  with due as (
    select j.id
      from public.approval_email_outbox j
      join public.profiles p on p.id=j.user_id
     where p.membership_status='approved' and j.attempts<8
       and ((j.status in ('pending','retry') and j.next_attempt_at<=now())
         or (j.status='processing' and j.locked_at<now()-interval '10 minutes'))
     order by j.created_at,j.id
     limit least(greatest(coalesce(p_limit,10),1),50)
     for update of j skip locked
  )
  update public.approval_email_outbox j
     set status='processing',attempts=j.attempts+1,
         claim_token=gen_random_uuid(),locked_at=now(),last_error=null
    from due
   where j.id=due.id
  returning j.*;
end $$;
revoke all on function public.claim_approval_email_jobs(integer) from public,anon,authenticated;
grant execute on function public.claim_approval_email_jobs(integer) to service_role;

-- Finish only the current claim. Delayed workers cannot overwrite the result
-- of a newer claim. Failed attempts back off from 2 to 128 minutes.
create or replace function public.finish_approval_email_job(
  p_id uuid,
  p_claim_token uuid,
  p_success boolean,
  p_provider_message_id text default null,
  p_error text default null
)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required';
  end if;
  if p_success is null then
    raise exception 'Delivery result is required';
  end if;

  update public.approval_email_outbox j
     set status=case when p_success then 'sent'
                     when j.attempts>=8 then 'failed' else 'retry' end,
         sent_at=case when p_success then now() else null end,
         next_attempt_at=case when p_success or j.attempts>=8 then j.next_attempt_at
                              else now()+make_interval(mins=>power(2,j.attempts)::integer) end,
         provider_message_id=case when p_success then left(p_provider_message_id,256) else null end,
         last_error=case when p_success then null
                         else left(coalesce(nullif(p_error,''),'Email delivery failed'),500) end,
         claim_token=null,locked_at=null
   where j.id=p_id and j.claim_token=p_claim_token and j.status='processing';
  if not found then
    raise exception 'Email job is not currently claimed with this token';
  end if;
end $$;
revoke all on function public.finish_approval_email_job(uuid,uuid,boolean,text,text)
  from public,anon,authenticated;
grant execute on function public.finish_approval_email_job(uuid,uuid,boolean,text,text)
  to service_role;

-- To manually retry a failed job after fixing its delivery problem, a project
-- owner can use SQL Editor to set status='retry', attempts=0 and
-- next_attempt_at=now() for that job. This is intentionally not a web RPC.

-- LEGACY SOURCE: upgrade_teacher_promotions.sql
-- Run after upgrade_roles_investors.sql, upgrade_approval_emails.sql and
-- upgrade_course_journey.sql in the Supabase SQL Editor.
-- Administrators may promote an approved member without re-approving the
-- account. A role change does not enqueue a second membership approval email.

create or replace function public.promote_member_to_teacher(p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_role text; v_membership_status text;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_user is null or p_user = (select auth.uid()) then
    raise exception 'Select another member to promote';
  end if;

  select p.role, p.membership_status into v_role, v_membership_status
    from public.profiles p where p.id = p_user for update;
  if not found then raise exception 'Member not found'; end if;
  if v_role <> 'member' or v_membership_status <> 'approved' then
    raise exception 'Only an approved member can be promoted to teacher';
  end if;
  if not exists (
    select 1 from auth.users u where u.id = p_user and u.email_confirmed_at is not null
  ) then raise exception 'The member must verify their email first'; end if;

  update public.profiles
     set role = 'teacher', application_type = 'teacher'
   where id = p_user;

  -- Keep an unsent first-approval email aligned with the new role. A worker
  -- that claimed the old member job may fail its current check; leave one
  -- retry available even if that claim was the eighth attempt.
  update public.approval_email_outbox j
     set application_type = 'teacher',
         attempts = case when j.status = 'processing' then least(j.attempts, 7)
                         else j.attempts end
   where j.user_id = p_user and j.status <> 'sent';

  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()), 'member_promoted_to_teacher', 'profile', p_user);
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    values (p_user, 'membership', 'Teacher access is ready. Complete your teaching profile.', 'teacher', p_user);
end $$;
revoke all on function public.promote_member_to_teacher(uuid) from public, anon, authenticated;
grant execute on function public.promote_member_to_teacher(uuid) to authenticated;

-- For a new member applicant, change the requested role inside the same
-- transaction as the existing approval review. The review function and
-- approval trigger still require verified email and a complete application;
-- they create the usual audit entry, notification and first approval email.
create or replace function public.approve_member_applicant_as_teacher(p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_role text; v_type text; v_status text;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_user is null or p_user = (select auth.uid()) then
    raise exception 'Select another applicant to approve';
  end if;

  select p.role, p.application_type, p.membership_status into v_role, v_type, v_status
    from public.profiles p where p.id = p_user for update;
  if not found then raise exception 'Applicant not found'; end if;
  if v_role <> 'member' or v_type <> 'member' or v_status not in ('pending', 'rejected') then
    raise exception 'Select a pending or rejected member applicant';
  end if;
  if not exists (
    select 1 from auth.users u where u.id = p_user and u.email_confirmed_at is not null
  ) then raise exception 'The applicant must verify their email first'; end if;

  update public.profiles set application_type = 'teacher' where id = p_user;
  perform public.review_membership(p_user, 'approved');
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    values (p_user, 'membership', 'Teacher access is ready. Complete your teaching profile.', 'teacher', p_user);
  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()), 'member_application_approved_as_teacher', 'profile', p_user);
end $$;
revoke all on function public.approve_member_applicant_as_teacher(uuid) from public, anon, authenticated;
grant execute on function public.approve_member_applicant_as_teacher(uuid) to authenticated;

-- The teacher completes this form after gaining access. It records practical
-- teaching interests and availability; it is not a credential verification.
create table if not exists public.teacher_profiles (
  teacher_id uuid primary key references public.profiles(id) on delete cascade,
  track text not null check (track in (
    'Controls and Automation', 'Software and Programming',
    'Electronics and Robotics', 'AI & Machine Learning'
  )),
  experience text not null check (char_length(btrim(experience)) between 20 and 2000),
  practical_focus text not null check (char_length(btrim(practical_focus)) between 20 and 2000),
  availability text not null check (char_length(btrim(availability)) between 5 and 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.touch_teacher_profile_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;
revoke all on function public.touch_teacher_profile_updated_at() from public, anon, authenticated;
drop trigger if exists touch_teacher_profile_updated_at on public.teacher_profiles;
create trigger touch_teacher_profile_updated_at before update on public.teacher_profiles
  for each row execute function public.touch_teacher_profile_updated_at();

alter table public.teacher_profiles enable row level security;
revoke all on public.teacher_profiles from public, anon, authenticated;
grant select on public.teacher_profiles to authenticated;
grant insert(teacher_id, track, experience, practical_focus, availability)
