  with check (public.is_teacher() and teacher_id = (select auth.uid()));

-- LEGACY SOURCE: upgrade_founder_teaching_roles.sql
-- Run after upgrade_teacher_promotions.sql, upgrade_course_journey.sql and
-- upgrade_approval_emails.sql. An approved founder has teaching access by
-- default; administrators may pause it without removing founder leadership.
-- Public founder cards are independent records, not linked to user profiles.

alter table public.profiles
  add column if not exists founder_teaching_enabled boolean not null default true;
-- All founders in the existing directory can teach on installation. A founder
-- whose teaching access is later paused keeps that explicit choice on reruns.
revoke update(founder_teaching_enabled) on public.profiles from anon, authenticated;

create or replace function public.reset_founder_teaching_on_role_change()
returns trigger language plpgsql set search_path = '' as $$
begin
  if old.role is distinct from new.role then
    -- An accepted invitation or approved founder application starts with
    -- teaching access, even after an older member/teacher role had disabled it.
    new.founder_teaching_enabled := (new.role = 'founder');
  end if;
  return new;
end $$;
revoke all on function public.reset_founder_teaching_on_role_change()
  from public, anon, authenticated;
drop trigger if exists reset_founder_teaching_on_role_change on public.profiles;
create trigger reset_founder_teaching_on_role_change
  before update of role on public.profiles for each row
  execute function public.reset_founder_teaching_on_role_change();

-- All existing teaching policies (course publishing, private submissions,
-- workshop review, learning uploads and teaching profile) call this helper.
create or replace function public.is_teacher()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.profiles p
     where p.id = (select auth.uid()) and p.membership_status = 'approved'
       and (p.role in ('teacher', 'admin')
         or (p.role = 'founder' and p.founder_teaching_enabled))
  );
$$;
revoke all on function public.is_teacher() from public, anon, authenticated;
grant execute on function public.is_teacher() to authenticated;

-- Keep workshops assigned to someone who can teach. Because workshops have
-- no archive/enrollment cutoff, even an empty workshop can receive learners.
-- Reassign all of the founder's workshops before ending teaching access.
create or replace function public.set_founder_teaching(p_user uuid, p_enabled boolean)
returns void language plpgsql security definer set search_path = '' as $$
declare v_enabled boolean;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_user is null or p_enabled is null or p_user = (select auth.uid()) then
    raise exception 'Select another founder and a teaching decision';
  end if;
  select p.founder_teaching_enabled into v_enabled
    from public.profiles p where p.id = p_user
      and p.role = 'founder' and p.membership_status = 'approved' for update;
  if not found then raise exception 'Select an approved founder'; end if;
  if v_enabled = p_enabled then return; end if;
  if not p_enabled and exists (
    select 1 from public.courses c where c.instructor_id = p_user
  ) then
    raise exception 'Reassign this founder''s workshops before removing teaching access';
  end if;
  update public.profiles set founder_teaching_enabled = p_enabled where id = p_user;
  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()),
      case when p_enabled then 'founder_teaching_enabled' else 'founder_teaching_disabled' end,
      'profile', p_user);
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    values (p_user, 'membership',
      case when p_enabled then 'Teaching access is ready. Complete your teaching profile.'
        else 'Teaching access has been paused by an administrator.' end,
      case when p_enabled then 'teacher' else 'application' end, p_user);
end $$;
revoke all on function public.set_founder_teaching(uuid, boolean)
  from public, anon, authenticated;
grant execute on function public.set_founder_teaching(uuid, boolean) to authenticated;

-- Change leadership role while retaining either a normal membership or a
-- teacher role. The latter preserves access to the teaching profile and
-- assigned workshop submissions. The public founder card is separate.
create or replace function public.remove_founder_role(p_user uuid, p_next_role text)
returns void language plpgsql security definer set search_path = '' as $$
declare v_email text;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_user is null or p_user = (select auth.uid()) then
    raise exception 'Select another founder';
  end if;
  if p_next_role is null or p_next_role not in ('member', 'teacher') then
    raise exception 'Choose member or teacher as the next role';
  end if;
  perform 1 from public.profiles p where p.id = p_user and p.role = 'founder' for update;
  if not found then raise exception 'Founder account not found'; end if;
  if p_next_role = 'member' and exists (
    select 1 from public.courses c where c.instructor_id = p_user
  ) then
    raise exception 'Reassign this founder''s workshops before removing teaching access';
  end if;

  -- Also update the application type: reviewing a suspended member later
  -- must not restore founder access from their original founder application.
  update public.profiles
     set role = p_next_role, application_type = p_next_role,
         founder_teaching_enabled = false
   where id = p_user;
  select lower(u.email) into v_email from auth.users u where u.id = p_user;
  if v_email is not null then
    -- A pending invitation must not let the same account immediately undo
    -- the administrator's decision. Existing accepted invitations stay put.
    update public.founder_invites set accepted_at = now()
      where email = v_email and accepted_at is null;
  end if;

  -- If the original first-approval message is still queued, its role label
  -- should match the account; a claimed worker can retry the updated job.
  update public.approval_email_outbox j
     set application_type = p_next_role,
         attempts = case when j.status = 'processing' then least(j.attempts, 7)
                         else j.attempts end
   where j.user_id = p_user and j.status <> 'sent';
  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()), 'founder_role_removed_to_' || p_next_role, 'profile', p_user);
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    values (p_user, 'membership',
      case when p_next_role = 'teacher'
        then 'Your founder role has changed to teacher. Teaching access remains available.'
        else 'Your founder role has changed to member. Teaching access has ended.' end,
      case when p_next_role = 'teacher' then 'teacher' else 'application' end, p_user);
end $$;
revoke all on function public.remove_founder_role(uuid, text)
  from public, anon, authenticated;
grant execute on function public.remove_founder_role(uuid, text) to authenticated;

-- A teacher may join founder leadership without losing the teaching studio,
-- teaching profile, learning materials or workshop assignments.
create or replace function public.assign_teacher_as_founder(p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_email text;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_user is null or p_user = (select auth.uid()) then
    raise exception 'Select another teacher to assign as founder';
  end if;
  perform 1 from public.profiles p where p.id = p_user
    and p.role = 'teacher' and p.membership_status = 'approved' for update;
  if not found then raise exception 'Select an approved teacher'; end if;
  select lower(u.email) into v_email from auth.users u
    where u.id = p_user and u.email_confirmed_at is not null;
  if v_email is null then raise exception 'The teacher must verify their email first'; end if;

  update public.profiles
     set role = 'founder', application_type = 'founder',
         founder_teaching_enabled = true
   where id = p_user;
  -- Prevent a previously outstanding invitation being accepted later as a
  -- second, confusing route to founder access.
  update public.founder_invites set accepted_at = now()
    where email = v_email and accepted_at is null;
  update public.approval_email_outbox j
     set application_type = 'founder',
         attempts = case when j.status = 'processing' then least(j.attempts, 7)
                         else j.attempts end
   where j.user_id = p_user and j.status <> 'sent';
  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()), 'teacher_promoted_to_founder', 'profile', p_user);
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    values (p_user, 'membership',
      'Founder access is ready. Your teaching studio remains available.',
      'founder', p_user);
end $$;
revoke all on function public.assign_teacher_as_founder(uuid)
  from public, anon, authenticated;
grant execute on function public.assign_teacher_as_founder(uuid) to authenticated;

-- Admins can assign teaching-enabled founders to older or transferred
-- workshops. Lock the teacher profile so a concurrent teaching revocation
-- cannot race with the assignment.
create or replace function public.assign_course_instructor(p_course uuid, p_teacher uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  perform 1 from public.profiles p where p.id = p_teacher
    and p.membership_status = 'approved'
    and (p.role in ('teacher', 'admin')
      or (p.role = 'founder' and p.founder_teaching_enabled)) for share;
  if not found then raise exception 'Select an approved teacher or teaching founder'; end if;
  update public.courses set instructor_id = p_teacher where id = p_course;
  if not found then raise exception 'Workshop not found'; end if;
end $$;
revoke all on function public.assign_course_instructor(uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.assign_course_instructor(uuid, uuid) to authenticated;

-- RLS alone can evaluate a course INSERT against an earlier snapshot of the
-- instructor's role. Hold a row lock on the assigned teacher until the course
-- INSERT commits, so an administrator cannot remove teaching rights between
-- authorization and the new workshop becoming visible.
create or replace function public.validate_course_instructor()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  -- The instructor FK uses ON DELETE SET NULL during account removal. Allow
  -- that cleanup on UPDATE; new workshops still require an eligible teacher.
  if tg_op = 'UPDATE' and new.instructor_id is null then return new; end if;
  perform 1 from public.profiles p where p.id = new.instructor_id
    and p.membership_status = 'approved'
    and (p.role in ('teacher', 'admin')
      or (p.role = 'founder' and p.founder_teaching_enabled)) for share;
  if not found then
    raise exception 'The workshop instructor must be an approved teacher or teaching founder';
  end if;
  return new;
end $$;
revoke all on function public.validate_course_instructor()
  from public, anon, authenticated;
drop trigger if exists validate_course_instructor_insert on public.courses;
create trigger validate_course_instructor_insert
  before insert on public.courses for each row
  execute function public.validate_course_instructor();
drop trigger if exists validate_course_instructor_update on public.courses;
create trigger validate_course_instructor_update
  before update of instructor_id on public.courses for each row
  execute function public.validate_course_instructor();

-- Public founder cards have no profile FK. Removing an account's founder
-- access does not identify which public card to delete, so expose a separate
-- administrator-only delete operation on those cards.
grant delete on public.founders to authenticated;
drop policy if exists "Admins remove public founder cards" on public.founders;
create policy "Admins remove public founder cards"
  on public.founders for delete to authenticated using (public.is_admin());

create or replace function public.audit_founder_card_removal()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()), 'founder_card_removed', 'founder_card', old.id);
  return old;
end $$;
revoke all on function public.audit_founder_card_removal()
  from public, anon, authenticated;
drop trigger if exists audit_founder_card_removal on public.founders;
create trigger audit_founder_card_removal
  after delete on public.founders for each row
  execute function public.audit_founder_card_removal();

-- LEGACY SOURCE: upgrade_course_planning.sql
-- Run after upgrade_course_journey.sql, upgrade_founder_teaching_roles.sql,
-- upgrade_privacy_requests.sql and upgrade_membership_collaboration.sql.
-- A workshop's deadline is informational: learners may still submit work or
-- revisions after it. Existing workshop inserts without a date still work.

begin;

alter table public.courses
  add column if not exists submission_due_at timestamptz;
alter table public.courses
  drop constraint if exists courses_submission_schedule_check;
alter table public.courses
  add constraint courses_submission_schedule_check
    check (starts_at is null or submission_due_at is null
      or submission_due_at > starts_at);

-- The course journey upgrade grants INSERT by column. Let a teacher set an
-- initial deadline without granting direct UPDATE of a published workshop.
grant insert(submission_due_at) on public.courses to authenticated;
revoke update on public.courses from public,anon,authenticated;

-- An administrator may edit any schedule. An approved teacher or teaching
-- founder may edit only their assigned workshop. Lock the actor's profile and
-- then the course so role changes or reassignment cannot race the decision.
create or replace function public.update_course_schedule(
  p_course uuid,
  p_starts_at timestamptz,
  p_due_at timestamptz
)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_admin boolean;
  v_course public.courses%rowtype;
begin
  select p.role = 'admin' into v_admin
    from public.profiles p
   where p.id = (select auth.uid())
     and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  if p_starts_at is not null and p_due_at is not null
     and p_due_at <= p_starts_at then
    raise exception 'The submission deadline must be after the workshop start';
  end if;
  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can update this workshop';
  end if;
  if v_course.starts_at is not distinct from p_starts_at
     and v_course.submission_due_at is not distinct from p_due_at then
    return;
  end if;

  update public.courses
     set starts_at = p_starts_at, submission_due_at = p_due_at
   where id = p_course;
  insert into public.audit_events(actor_id,action,target_type,target_id)
    values ((select auth.uid()),'course_schedule_updated','course',p_course);
  insert into public.notifications(user_id,kind,title,target_type,target_id)
    select e.learner_id,'course',
           'Workshop schedule updated: ' || v_course.title,'course',p_course
      from public.course_enrollments e
     where e.course_id = p_course and e.status = 'enrolled';
end $$;
revoke all on function public.update_course_schedule(uuid,timestamptz,timestamptz)
  from public,anon,authenticated;
grant execute on function public.update_course_schedule(uuid,timestamptz,timestamptz)
  to authenticated;

-- Assigned teachers and admins can add an approved club learner by their
-- verified sign-in email. The function reveals no email or profile fields.
-- A repeated request returns the existing enrollment without a duplicate
-- notification; a completed enrollment is not reset.
create or replace function public.assign_course_learner(
  p_course uuid,
  p_email text
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_admin boolean;
  v_course public.courses%rowtype;
  v_email text := lower(btrim(p_email));
  v_learner uuid;
  v_enrollment uuid;
begin
  select p.role = 'admin' into v_admin
    from public.profiles p
   where p.id = (select auth.uid())
     and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can enroll learners';
  end if;
  if v_email is null or char_length(v_email) not between 3 and 320 then
    raise exception 'Enter the learner''s sign-in email';
  end if;

  select p.id into v_learner
    from auth.users u
    join public.profiles p on p.id = u.id
   where lower(u.email) = v_email
     and u.email_confirmed_at is not null
     and p.membership_status = 'approved'
     and p.role in ('member','teacher','founder','admin')
   for share of p;
  if not found then
    raise exception 'No eligible approved club member found for that email';
  end if;

  insert into public.course_enrollments(course_id,learner_id)
    values (p_course,v_learner)
    on conflict (course_id,learner_id) do nothing
    returning id into v_enrollment;
  if v_enrollment is null then
    select id into v_enrollment from public.course_enrollments
     where course_id = p_course and learner_id = v_learner;
    return v_enrollment;
  end if;

  insert into public.audit_events(actor_id,action,target_type,target_id)
    values ((select auth.uid()),'course_learner_assigned','course',p_course);
  insert into public.notifications(user_id,kind,title,target_type,target_id)
    values (v_learner,'course','You were enrolled in: ' || v_course.title,'course',p_course);
  return v_enrollment;
end $$;
revoke all on function public.assign_course_learner(uuid,text)
  from public,anon,authenticated;
grant execute on function public.assign_course_learner(uuid,text)
  to authenticated;

-- Removal is limited to an untouched active enrollment. Locking that row
-- serializes with the existing submission trigger, which locks the same row
-- before accepting a learner's work.
create or replace function public.unassign_course_learner(
  p_course uuid,
  p_learner uuid
)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_admin boolean;
  v_course public.courses%rowtype;
  v_enrollment public.course_enrollments%rowtype;
begin
  select p.role = 'admin' into v_admin
    from public.profiles p
   where p.id = (select auth.uid())
     and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can remove learners';
  end if;

  select * into v_enrollment from public.course_enrollments
   where course_id = p_course and learner_id = p_learner for update;
  if not found then return; end if;
  if v_enrollment.status <> 'enrolled'
     or exists (select 1 from public.course_submissions
                 where course_id = p_course and learner_id = p_learner)
     or exists (select 1 from public.course_completions
                 where course_id = p_course and learner_id = p_learner) then
    raise exception 'A learner with submitted or completed work cannot be removed';
  end if;

  delete from public.course_enrollments where id = v_enrollment.id;
  insert into public.audit_events(actor_id,action,target_type,target_id)
    values ((select auth.uid()),'course_learner_unassigned','course',p_course);
  insert into public.notifications(user_id,kind,title,target_type,target_id)
    values (p_learner,'course','You were removed from: ' || v_course.title,'course',p_course);
end $$;
revoke all on function public.unassign_course_learner(uuid,uuid)
  from public,anon,authenticated;
grant execute on function public.unassign_course_learner(uuid,uuid)
  to authenticated;

-- Profile privacy still hides the rest of a private learner's directory
-- record. Teachers see only names of learners in their own workshops;
-- administrators see all rosters. Neither receives email or profile details.
create or replace function public.teacher_course_roster()
returns table(course_id uuid, learner_id uuid, full_name text, status text)
language sql stable security definer set search_path = '' as $$
  select e.course_id,e.learner_id,p.full_name,e.status
    from public.course_enrollments e
    join public.courses c on c.id = e.course_id
    join public.profiles p on p.id = e.learner_id
   where public.is_admin()
      or (public.is_teacher() and c.instructor_id = (select auth.uid()));
$$;
revoke all on function public.teacher_course_roster()
  from public,anon,authenticated;
grant execute on function public.teacher_course_roster() to authenticated;

-- A learner's own enrollment appears in the assigned instructor's inbox.
-- Teacher/admin assignments are handled by the RPC above, so they do not
-- create a redundant notification for the actor.
create or replace function public.notify_course_self_enrollment()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_instructor uuid;
  v_title text;
begin
  if new.learner_id is distinct from (select auth.uid()) then return new; end if;
  select c.instructor_id,c.title into v_instructor,v_title
    from public.courses c where c.id = new.course_id;
  if v_instructor is not null and v_instructor <> new.learner_id then
    insert into public.notifications(user_id,kind,title,target_type,target_id)
      values (v_instructor,'course',
        'New learner enrolled in: ' || v_title,'teacher',new.course_id);
  end if;
  return new;
end $$;
revoke all on function public.notify_course_self_enrollment()
  from public,anon,authenticated;
drop trigger if exists notify_course_self_enrollment on public.course_enrollments;
create trigger notify_course_self_enrollment
  after insert on public.course_enrollments
  for each row execute function public.notify_course_self_enrollment();

commit;

-- LEGACY SOURCE: upgrade_private_applications.sql
-- Run after upgrade_approval_emails.sql and upgrade_privacy_requests.sql.
-- Application answers were previously columns on profiles. A member allowed
-- to see a profile row could also SELECT its application_reason despite the UI
-- hiding it. Keep answers in a separate table with its own RLS policies.
-- Do not rerun the older membership / approval migrations after this upgrade.
-- Publish the compatible website before running this migration: the old form
-- writes profiles.application_reason and will stop working once it is removed.

begin;

do $$
begin
  if to_regclass('public.approval_email_history') is null
     or to_regclass('public.approval_email_outbox') is null
     or to_regclass('public.audit_events') is null
     or to_regclass('public.notifications') is null then
    raise exception 'Run upgrade_approval_emails.sql before this migration';
  end if;
  if not exists (
    select 1 from pg_trigger
     where tgrelid = 'public.profiles'::regclass
       and tgname = 'queue_approval_email_on_approval' and not tgisinternal
  ) then
    raise exception 'Approval email trigger missing; run upgrade_approval_emails.sql first';
  end if;
end $$;

create table if not exists public.application_answers (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  reason text not null,
  updated_at timestamptz not null default now()
);

-- Copy existing nonempty answers without trimming their original wording.
-- Dynamic SQL makes a rerun safe once the original column has been dropped.
do $$
begin
  if exists (
    select 1 from pg_attribute
     where attrelid = 'public.profiles'::regclass
       and attname = 'application_reason' and not attisdropped
  ) then
    execute $copy$
      insert into public.application_answers (user_id, reason)
      select p.id, p.application_reason
        from public.profiles p
       where nullif(btrim(p.application_reason), '') is not null
      on conflict (user_id) do nothing
    $copy$;
  end if;
end $$;

alter table public.application_answers enable row level security;
revoke all on public.application_answers from public, anon, authenticated;
grant select, delete on public.application_answers to authenticated;
grant insert (user_id, reason) on public.application_answers to authenticated;
grant update (reason) on public.application_answers to authenticated;
grant select on public.application_answers to service_role;

drop policy if exists "Applicants and admins read answers" on public.application_answers;
create policy "Applicants and admins read answers"
  on public.application_answers for select to authenticated
  using (user_id = (select auth.uid()) or public.is_admin());

drop policy if exists "Applicants submit answers" on public.application_answers;
create policy "Applicants submit answers"
  on public.application_answers for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.profiles p where p.id = (select auth.uid())
        and p.membership_status in ('pending', 'rejected')
    )
  );

drop policy if exists "Applicants edit answers" on public.application_answers;
create policy "Applicants edit answers"
  on public.application_answers for update to authenticated
  using (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.profiles p where p.id = (select auth.uid())
        and p.membership_status in ('pending', 'rejected')
    )
  )
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.profiles p where p.id = (select auth.uid())
        and p.membership_status in ('pending', 'rejected')
    )
  );

drop policy if exists "Applicants withdraw answers" on public.application_answers;
create policy "Applicants withdraw answers"
  on public.application_answers for delete to authenticated
  using (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.profiles p where p.id = (select auth.uid())
        and p.membership_status in ('pending', 'rejected')
    )
  );

create or replace function public.touch_application_answer_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;
revoke all on function public.touch_application_answer_updated_at()
  from public, anon, authenticated;
drop trigger if exists touch_application_answer_updated_at on public.application_answers;
create trigger touch_application_answer_updated_at
before update on public.application_answers for each row
execute function public.touch_application_answer_updated_at();

-- Recreate both guards before dropping the profile column. Preserve the
-- existing exception for accounts known to have been approved previously.
create or replace function public.require_complete_application_for_approval()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.membership_status = 'approved'
     and old.membership_status is distinct from 'approved'
     and new.role in ('member', 'teacher', 'founder', 'investor') then
    if not exists (
      select 1 from auth.users u
       where u.id = new.id and u.email_confirmed_at is not null
    ) then
      raise exception 'Applicant must verify their email before approval';
    end if;
    if not exists (
      select 1 from public.application_answers a
       where a.user_id = new.id and nullif(btrim(a.reason), '') is not null
       for share
    ) and not exists (
      select 1 from public.approval_email_history h where h.user_id = new.id
    ) then
      raise exception 'Applicant must submit a reason for joining before approval';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.require_complete_application_for_approval()
  from public, anon, authenticated;

create or replace function public.review_membership(p_user uuid, p_status text)
returns void language plpgsql security definer set search_path = '' as $$
declare v_type text; v_status text;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_status not in ('approved', 'rejected', 'suspended') then
    raise exception 'Invalid review decision';
  end if;
  if p_user = auth.uid() then raise exception 'You cannot review your own account'; end if;

  select p.application_type, p.membership_status into v_type, v_status
    from public.profiles p where p.id = p_user and p.role <> 'admin' for update;
  if not found then raise exception 'Applicant not found or cannot be changed'; end if;

  if p_status = 'approved' then
    if not exists (
      select 1 from auth.users u
       where u.id = p_user and u.email_confirmed_at is not null
    ) then
      raise exception 'Applicant must verify their email before approval';
    end if;
    if v_status in ('pending', 'rejected')
       and not exists (
         select 1 from public.application_answers a
          where a.user_id = p_user and nullif(btrim(a.reason), '') is not null
          for share
       ) and not exists (
         select 1 from public.approval_email_history h where h.user_id = p_user
       ) then
      raise exception 'Applicant must submit a reason for joining before approval';
    end if;
    update public.profiles set membership_status = 'approved', role = v_type
      where id = p_user;
  else
    update public.profiles set membership_status = p_status where id = p_user;
  end if;

  insert into public.audit_events(actor_id, action, target_type, target_id)
    values (auth.uid(), 'membership_' || p_status || '_' || v_type, 'profile', p_user);
  if p_status = 'approved' then
    insert into public.notifications(user_id, kind, title, target_type, target_id)
      values (p_user, 'membership', 'Your SPACE application was approved',
              'application', p_user);
  end if;
end $$;
revoke all on function public.review_membership(uuid, text) from public, anon;
grant execute on function public.review_membership(uuid, text) to authenticated;

-- All existing SELECT * profile queries now return only directory fields.
-- The DROP also removes the former column-level UPDATE grant. Functions in
-- the installed code have been replaced above; do not rerun their old files.
alter table public.profiles drop column if exists application_reason;

commit;

-- LEGACY SOURCE: upgrade_course_classroom_access.sql
-- Run after upgrade_course_planning.sql, upgrade_teacher_materials.sql and
-- upgrade_founder_teaching_roles.sql. Keep the catalog open to approved club
-- members; only a course's learners and teaching lead see its private files.
-- Safe to rerun. Do not rerun the older teacher-materials migration afterward.

begin;

-- A private course file must never become a general-library file as a side
-- effect of deleting the workshop. Preserve the course until the material is
-- deliberately handled by an administrator.
alter table public.learning_materials
  drop constraint if exists learning_materials_course_id_fkey;
alter table public.learning_materials
  add constraint learning_materials_course_id_fkey
    foreign key (course_id) references public.courses(id) on delete restrict;

drop policy if exists "Club reads learning materials" on public.learning_materials;
create policy "Club reads learning materials" on public.learning_materials
  for select to authenticated using (
    public.is_approved()
    and (hidden_at is null or public.is_admin())
    and (
      course_id is null or public.is_admin()
      or (public.is_teacher() and exists (
        select 1 from public.courses c
         where c.id = learning_materials.course_id
           and c.instructor_id = (select auth.uid())
      ))
      or exists (
        select 1 from public.course_enrollments e
         where e.course_id = learning_materials.course_id
           and e.learner_id = (select auth.uid())
      )
    )
  );

drop policy if exists "Teachers publish learning materials" on public.learning_materials;
create policy "Teachers publish learning materials" on public.learning_materials
  for insert to authenticated with check (
    public.is_teacher()
    and uploaded_by = (select auth.uid())
    and hidden_at is null
    and split_part(storage_path, '/', 1) = (select auth.uid()::text)
    and (
      course_id is null or public.is_admin()
      or exists (
        select 1 from public.courses c
         where c.id = learning_materials.course_id
           and c.instructor_id = (select auth.uid())
      )
    )
  );

-- The Storage API can require SELECT even when removing an unlinked upload.
-- A SECURITY DEFINER lookup checks the actual table rather than the caller's
-- filtered material rows, so a former instructor cannot delete a published
-- file merely because its course is no longer visible to them.
create or replace function public.is_unlinked_learning_file(p_path text)
returns boolean language sql stable security definer set search_path = '' as $$
  select public.is_teacher()
    and split_part(coalesce(p_path, ''), '/', 1) = (select auth.uid()::text)
    and not exists (
    select 1 from public.learning_materials m where m.storage_path = p_path
  );
$$;
revoke all on function public.is_unlinked_learning_file(text)
  from public, anon, authenticated;
grant execute on function public.is_unlinked_learning_file(text) to authenticated;

drop policy if exists "Club downloads learning files" on storage.objects;
create policy "Club downloads learning files" on storage.objects
  for select to authenticated using (
    bucket_id = 'club-learning' and public.is_approved() and (
      exists (
        select 1 from public.learning_materials m
         where m.storage_path = name and m.hidden_at is null
           and (
             m.course_id is null or public.is_admin()
             or (public.is_teacher() and exists (
               select 1 from public.courses c
                where c.id = m.course_id and c.instructor_id = (select auth.uid())
             ))
             or exists (
               select 1 from public.course_enrollments e
                where e.course_id = m.course_id
                  and e.learner_id = (select auth.uid())
             )
           )
      )
      or (
        public.is_teacher()
        and (storage.foldername(name))[1] = (select auth.uid()::text)
        and public.is_unlinked_learning_file(name)
      )
    )
  );

drop policy if exists "Teachers clean up own learning files" on storage.objects;
create policy "Teachers clean up own learning files" on storage.objects
  for delete to authenticated using (
    bucket_id = 'club-learning' and public.is_teacher()
    and (storage.foldername(name))[1] = (select auth.uid()::text)
    and public.is_unlinked_learning_file(name)
  );

-- Existing workshop schedule changes use an RPC. Treat course content edits
-- the same way: course reassignment and privileged columns stay unavailable.
create or replace function public.update_course_content(
  p_course uuid,
  p_title text,
  p_category text,
  p_level text,
  p_description text,
  p_resource_url text
)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_admin boolean;
  v_course public.courses%rowtype;
  v_title text := btrim(p_title);
  v_category text := btrim(p_category);
  v_level text := btrim(p_level);
  v_description text := btrim(p_description);
  v_resource_url text := nullif(btrim(p_resource_url), '');
begin
  select p.role = 'admin' into v_admin
    from public.profiles p
   where p.id = (select auth.uid())
     and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  if v_title is null or char_length(v_title) not between 3 and 160 then
    raise exception 'Use a workshop title of 3 to 160 characters';
  end if;
  if v_category is null or v_category not in (
    'Controls and Automation','Software and Programming',
    'Electronics and Robotics','AI & Machine Learning'
  ) then raise exception 'Select one of the four learning tracks'; end if;
  if v_level is null or v_level not in ('Beginner','Intermediate','Advanced') then
    raise exception 'Choose a valid workshop level';
  end if;
  if v_description is null or char_length(v_description) not between 20 and 5000 then
    raise exception 'Describe the practical build in 20 to 5000 characters';
  end if;
  if v_resource_url is not null and (
    char_length(v_resource_url) > 1000
    or v_resource_url !~* '^https://[^[:space:]]+$'
  ) then raise exception 'Use an HTTPS resource link'; end if;

  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can edit this workshop';
  end if;
  if v_course.title is not distinct from v_title
    and v_course.category is not distinct from v_category
    and v_course.level is not distinct from v_level
    and v_course.description is not distinct from v_description
    and v_course.resource_url is not distinct from v_resource_url then return; end if;

  update public.courses set title = v_title, category = v_category,
    level = v_level, description = v_description,
    resource_url = v_resource_url where id = p_course;
  insert into public.audit_events(actor_id, action, target_type, target_id)
    values ((select auth.uid()), 'course_content_updated', 'course', p_course);
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    select e.learner_id, 'course', 'Workshop details updated: ' || v_title,
      'course', p_course
      from public.course_enrollments e
     where e.course_id = p_course and e.status = 'enrolled'
       and e.learner_id <> (select auth.uid());
end $$;
revoke all on function public.update_course_content(uuid,text,text,text,text,text)
  from public, anon, authenticated;
grant execute on function public.update_course_content(uuid,text,text,text,text,text)
  to authenticated;

-- Keep the notice itself generic. Build notes, feedback and evidence remain
-- restricted by the existing submissions and evidence policies.
create or replace function public.notify_course_submission()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_teacher uuid;
  v_title text;
begin
  select c.instructor_id, c.title into v_teacher, v_title
    from public.courses c where c.id = new.course_id;
  if v_teacher is not null and v_teacher <> new.learner_id and exists (
    select 1 from public.profiles p
     where p.id = v_teacher and p.membership_status = 'approved'
       and (p.role in ('teacher','admin')
         or (p.role = 'founder' and p.founder_teaching_enabled))
  ) then
    insert into public.notifications(user_id, kind, title, target_type, target_id)
      values (v_teacher, 'course', 'Project ready for review: ' || v_title,
        'teacher', new.course_id);
  else
    -- An unassigned workshop, or a teacher submitting their own project,
    -- needs an administrator to review it.
    insert into public.notifications(user_id, kind, title, target_type, target_id)
      select p.id, 'course', 'Project ready for review: ' || v_title,
        'teacher', new.course_id
        from public.profiles p
       where p.role = 'admin' and p.membership_status = 'approved'
         and p.id <> new.learner_id;
  end if;
  return new;
end $$;
revoke all on function public.notify_course_submission()
  from public, anon, authenticated;
drop trigger if exists notify_course_submission on public.course_submissions;
create trigger notify_course_submission after insert on public.course_submissions
  for each row execute function public.notify_course_submission();

create or replace function public.notify_course_feedback()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_title text;
begin
  select c.title into v_title from public.courses c where c.id = new.course_id;
  insert into public.notifications(user_id, kind, title, target_type, target_id)
    values (new.learner_id, 'course',
      case when new.review_status = 'accepted' then 'Project accepted: '
        else 'Revision requested: ' end || v_title,
      'course', new.course_id);
  return new;
end $$;
revoke all on function public.notify_course_feedback()
  from public, anon, authenticated;
drop trigger if exists notify_course_feedback on public.course_submissions;
create trigger notify_course_feedback
  after update of review_status on public.course_submissions
  for each row
  when (old.review_status = 'submitted'
    and new.review_status in ('accepted','revision_requested'))
  execute function public.notify_course_feedback();

commit;

-- LEGACY SOURCE: upgrade_course_lifecycle_reviews.sql
-- Run after upgrade_course_classroom_access.sql, upgrade_course_planning.sql,
-- upgrade_course_journey.sql and upgrade_founder_teaching_roles.sql.
-- Safe to rerun. New enrollment closes when a course ends; existing learners
-- retain access to submissions, revisions, feedback and course files.

begin;

alter table public.courses add column if not exists status text;
update public.courses set status = 'active' where status is null;
alter table public.courses alter column status set default 'active';
alter table public.courses alter column status set not null;
alter table public.courses drop constraint if exists courses_status_check;
alter table public.courses add constraint courses_status_check
  check (status in ('active','ended','archived'));
revoke update(status), insert(status) on public.courses from public, anon, authenticated;

alter table public.course_submissions
  add column if not exists seen_at timestamptz;
alter table public.course_submissions
  add column if not exists seen_by uuid references public.profiles(id) on delete set null;
-- Previously reviewed attempts were necessarily seen during feedback.
update public.course_submissions
   set seen_at = reviewed_at, seen_by = reviewed_by
 where review_status <> 'submitted' and reviewed_at is not null
   and seen_at is null;
revoke update(seen_at,seen_by) on public.course_submissions
  from public, anon, authenticated;

-- The enrollment SELECT policy joins courses for teacher access. Use a
-- narrowly scoped definer helper here to avoid recursive RLS evaluation.
create or replace function public.has_course_enrollment(p_course uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.course_enrollments e
     where e.course_id = p_course and e.learner_id = (select auth.uid())
  );
$$;
revoke all on function public.has_course_enrollment(uuid)
  from public, anon, authenticated;
grant execute on function public.has_course_enrollment(uuid) to authenticated;

-- Active and ended workshops remain in the club catalog. Archive hides a
-- workshop from everyone except its enrolled learners, assigned teacher and
-- administrators, preserving every private record and uploaded file.
drop policy if exists "Members view courses" on public.courses;
create policy "Members view courses" on public.courses
  for select to authenticated using (
    public.is_approved() and (
      status <> 'archived' or public.is_admin()
      or (public.is_teacher() and instructor_id = (select auth.uid()))
      or public.has_course_enrollment(id)
    )
  );

-- Both browser enrollment and assignment RPCs must fail once a workshop has
-- ended. RLS protects browser INSERTs; the trigger locks the course row to
-- serialize against a simultaneous end/archive/delete by its teacher.
drop policy if exists "Approved learners enroll themselves" on public.course_enrollments;
create policy "Approved learners enroll themselves" on public.course_enrollments
  for insert to authenticated with check (
    public.is_approved() and learner_id = (select auth.uid())
    and status = 'enrolled' and completed_at is null
    and exists (
      select 1 from public.courses c
       where c.id = course_id and c.status = 'active'
    )
  );

create or replace function public.require_active_course_for_enrollment()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_status text;
begin
  select c.status into v_status from public.courses c
   where c.id = new.course_id for share;
  if v_status is distinct from 'active' then
    raise exception 'This workshop is no longer accepting new students';
  end if;
  return new;
end $$;
revoke all on function public.require_active_course_for_enrollment()
  from public, anon, authenticated;
drop trigger if exists require_active_course_for_enrollment on public.course_enrollments;
create trigger require_active_course_for_enrollment
  before insert on public.course_enrollments for each row
  execute function public.require_active_course_for_enrollment();

-- Preserve the original email lookup, approval checks and assignment notice.
-- Add a status check even though the trigger also protects privileged INSERTs.
create or replace function public.assign_course_learner(
  p_course uuid,
  p_email text
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_admin boolean;
  v_course public.courses%rowtype;
  v_email text := lower(btrim(p_email));
  v_learner uuid;
  v_enrollment uuid;
begin
  select p.role = 'admin' into v_admin
    from public.profiles p
   where p.id = (select auth.uid())
     and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can enroll learners';
  end if;
  if v_course.status <> 'active' then
    raise exception 'This workshop is no longer accepting new students';
  end if;
  if v_email is null or char_length(v_email) not between 3 and 320 then
    raise exception 'Enter the learner''s sign-in email';
  end if;

  select p.id into v_learner
    from auth.users u
    join public.profiles p on p.id = u.id
   where lower(u.email) = v_email
     and u.email_confirmed_at is not null
     and p.membership_status = 'approved'
     and p.role in ('member','teacher','founder','admin')
   for share of p;
  if not found then
    raise exception 'No eligible approved club member found for that email';
  end if;

  insert into public.course_enrollments(course_id,learner_id)
    values (p_course,v_learner)
    on conflict (course_id,learner_id) do nothing
    returning id into v_enrollment;
  if v_enrollment is null then
    select id into v_enrollment from public.course_enrollments
     where course_id = p_course and learner_id = v_learner;
    return v_enrollment;
  end if;

  insert into public.audit_events(actor_id,action,target_type,target_id)
    values ((select auth.uid()),'course_learner_assigned','course',p_course);
  insert into public.notifications(user_id,kind,title,target_type,target_id)
    values (v_learner,'course','You were enrolled in: ' || v_course.title,'course',p_course);
  return v_enrollment;
end $$;
revoke all on function public.assign_course_learner(uuid,text)
  from public, anon, authenticated;
grant execute on function public.assign_course_learner(uuid,text) to authenticated;

-- End closes new enrollment, but students already enrolled may still hand
-- in work, request help and receive feedback, including revisions.
create or replace function public.end_course(p_course uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_admin boolean; v_course public.courses%rowtype;
begin
  select p.role = 'admin' into v_admin from public.profiles p
   where p.id = (select auth.uid()) and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can end this workshop';
  end if;
  if v_course.status = 'ended' then return; end if;
  if v_course.status <> 'active' then
    raise exception 'An archived workshop cannot be ended again';
  end if;

  update public.courses set status = 'ended' where id = p_course;
  insert into public.audit_events(actor_id,action,target_type,target_id)
    values ((select auth.uid()),'course_ended','course',p_course);
  insert into public.notifications(user_id,kind,title,target_type,target_id)
    select e.learner_id,'course','Workshop ended: ' || v_course.title,
           'course',p_course
      from public.course_enrollments e
     where e.course_id = p_course and e.learner_id <> (select auth.uid());
end $$;
revoke all on function public.end_course(uuid) from public, anon, authenticated;
grant execute on function public.end_course(uuid) to authenticated;

-- A genuinely unused draft can be deleted; otherwise deletion only archives
-- it. Cascading enrollment/submission/completion FKs must never erase work.
create or replace function public.delete_course(p_course uuid)
returns text language plpgsql security definer set search_path = '' as $$
declare v_admin boolean; v_course public.courses%rowtype;
begin
  select p.role = 'admin' into v_admin from public.profiles p
   where p.id = (select auth.uid()) and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  select * into v_course from public.courses where id = p_course for update;
  if not found then raise exception 'Workshop not found'; end if;
  if not v_admin and v_course.instructor_id is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher can remove this workshop';
  end if;

  if not exists (select 1 from public.course_enrollments where course_id = p_course)
    and not exists (select 1 from public.course_submissions where course_id = p_course)
    and not exists (select 1 from public.course_completions where course_id = p_course)
    and not exists (select 1 from public.learning_materials where course_id = p_course)
    and not exists (
      -- An upload can exist before its submission row is committed. Do not
      -- strand even an unsubmitted file by hard deleting its workshop.
      select 1 from storage.objects o
       where o.bucket_id = 'club-course-evidence'
         and split_part(o.name, '/', 2) = p_course::text
    )
  then
    delete from public.courses where id = p_course;
    insert into public.audit_events(actor_id,action,target_type,target_id)
      values ((select auth.uid()),'course_deleted_unused','course',p_course);
    return 'deleted';
  end if;

  if v_course.status <> 'archived' then
    update public.courses set status = 'archived' where id = p_course;
    insert into public.audit_events(actor_id,action,target_type,target_id)
      values ((select auth.uid()),'course_archived','course',p_course);
    insert into public.notifications(user_id,kind,title,target_type,target_id)
      select e.learner_id,'course','Workshop archived: ' || v_course.title,
             'course',p_course
        from public.course_enrollments e
       where e.course_id = p_course and e.learner_id <> (select auth.uid());
  end if;
  return 'archived';
end $$;
revoke all on function public.delete_course(uuid) from public, anon, authenticated;
grant execute on function public.delete_course(uuid) to authenticated;

-- Seen is separate from reviewed: a teacher can acknowledge the project
-- without accepting it or requesting a revision. Only the current assigned
-- teacher or an administrator may acknowledge, never its author.
create or replace function public.mark_course_submission_seen(p_submission uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_admin boolean;
  v_course_id uuid;
  v_instructor uuid;
  v_submission public.course_submissions%rowtype;
begin
  select p.role = 'admin' into v_admin from public.profiles p
   where p.id = (select auth.uid()) and p.membership_status = 'approved'
     and (p.role in ('teacher','admin')
       or (p.role = 'founder' and p.founder_teaching_enabled))
   for share;
  if not found then raise exception 'Teacher or administrator access required'; end if;

  select s.course_id into v_course_id
    from public.course_submissions s where s.id = p_submission;
  if not found then raise exception 'Submission not found'; end if;
  select c.instructor_id into v_instructor from public.courses c
    where c.id = v_course_id for share;
  if not v_admin and v_instructor is distinct from (select auth.uid()) then
    raise exception 'Only the assigned teacher may mark this submission seen';
  end if;
  select * into v_submission from public.course_submissions
    where id = p_submission for update;
  if v_submission.learner_id = (select auth.uid()) then
    raise exception 'You cannot mark your own work seen';
  end if;
  if not exists (
    select 1 from public.course_enrollments e
     where e.course_id = v_submission.course_id
       and e.learner_id = v_submission.learner_id
  ) then raise exception 'Submission learner is not enrolled'; end if;
  if v_submission.seen_at is not null or v_submission.review_status <> 'submitted'
  then return; end if;

  update public.course_submissions
     set seen_at = now(), seen_by = (select auth.uid())
   where id = p_submission;
  insert into public.audit_events(actor_id,action,target_type,target_id)
    values ((select auth.uid()),'course_submission_seen','course_submission',p_submission);
end $$;
revoke all on function public.mark_course_submission_seen(uuid)
  from public, anon, authenticated;
grant execute on function public.mark_course_submission_seen(uuid) to authenticated;

-- Existing review_course_submission() keeps its feedback/completion rules;
-- this trigger makes a successful review implicitly acknowledge the attempt.
create or replace function public.see_reviewed_course_submission()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if old.review_status = 'submitted'
    and new.review_status in ('accepted','revision_requested')
    and new.seen_at is null then
    new.seen_at := now();
    new.seen_by := (select auth.uid());
  end if;
  return new;
end $$;
revoke all on function public.see_reviewed_course_submission()
  from public, anon, authenticated;
drop trigger if exists see_reviewed_course_submission on public.course_submissions;
create trigger see_reviewed_course_submission
  before update of review_status on public.course_submissions
  for each row execute function public.see_reviewed_course_submission();

commit;

-- LEGACY SOURCE: upgrade_message_counts.sql
-- Run after upgrade_membership_collaboration.sql, upgrade_direct_messages.sql,
-- and upgrade_roles_investors.sql. Safe to rerun.
-- Unread counts are calculated on the server for the signed-in participant;
-- the client never needs to download all private messages to count them.

create or replace function public.club_unread_counts()
returns jsonb
language sql stable security definer set search_path = '' as $$
  with caller as (
    select auth.uid() as id
  ), permitted as (
    select c.id from caller c
      join public.profiles p on p.id=c.id
     where p.membership_status='approved'
       and p.role in ('member','teacher','founder','admin')
  ), channels as (
    select m.channel_id,count(*)::bigint as unread_count
      from public.channel_messages m
      cross join permitted p
      left join public.channel_reads r
        on r.channel_id=m.channel_id and r.user_id=p.id
     where m.author_id<>p.id
       and m.deleted_at is null
       and (r.last_read_at is null or m.created_at>r.last_read_at)
     group by m.channel_id
  ), messages as (
    select m.sender_id,count(*)::bigint as unread_count
      from public.direct_messages m
      join permitted p on p.id=m.recipient_id
      left join public.direct_message_reads r
        on r.user_id=p.id and r.peer_id=m.sender_id
     where r.last_read_at is null or m.created_at>r.last_read_at
     group by m.sender_id
  ), direct_peers as (
    select distinct case when m.sender_id=p.id then m.recipient_id else m.sender_id end as peer_id
      from public.direct_messages m
      join permitted p on m.sender_id=p.id or m.recipient_id=p.id
  )
  select case when exists(select 1 from permitted) then jsonb_build_object(
    'channels',coalesce((select jsonb_object_agg(channel_id::text,unread_count)
                           from channels),'{}'::jsonb),
    'direct_messages',coalesce((select jsonb_object_agg(sender_id::text,unread_count)
                                  from messages),'{}'::jsonb),
    'direct_peers',coalesce((select jsonb_agg(peer_id::text) from direct_peers),'[]'::jsonb),
    'direct_total',coalesce((select sum(unread_count) from messages),0)
  ) else null end;
$$;

revoke all on function public.club_unread_counts() from public,anon;
grant execute on function public.club_unread_counts() to authenticated;

