comment on function public.space_metrics(text,integer,uuid) is 'Read-only role-scoped SPACE metrics. SECURITY INVOKER preserves RLS. UTC calendar windows include today; snapshot cards say so explicitly.';
commit;

-- LEGACY SOURCE: upgrade_manual_metrics.sql
-- Run the entire file after upgrade_space_metrics.sql. Safe to rerun.
-- Manual observations never change enrollment, stock, orders or the finance ledger.
begin;
do $$ begin
 if to_regprocedure('public.space_metrics(text,integer,uuid)') is null then raise exception 'Run upgrade_space_metrics.sql first'; end if;
end $$;
create table if not exists public.space_manual_metrics(
 id uuid primary key default gen_random_uuid(),root_id uuid not null references public.space_manual_metrics(id),
 revision integer not null check(revision>0),supersedes_id uuid unique references public.space_manual_metrics(id),
 owner_id uuid not null references public.profiles(id),recorded_by uuid not null references public.profiles(id),
 scope text not null check(scope in ('membership','learning','teaching','inventory','finance','orders')),
 course_id uuid references public.courses(id) on delete restrict,
 label text not null check(length(trim(label)) between 3 and 100),
 unit text not null check(unit in ('count','hours','percent','GHS')),
 actual numeric(14,2) not null check(actual>=0 and actual<=100000000000 and actual::text not in ('NaN','Infinity','-Infinity')),
 target numeric(14,2) check(target>0 and target<=100000000000 and target::text not in ('NaN','Infinity','-Infinity')),
 observed_on date not null,source text not null check(length(trim(source)) between 3 and 160),
 note text not null default '' check(length(note)<=1000),
 client_token uuid not null,request_fingerprint text not null,created_at timestamptz not null default now(),
 unique(root_id,revision),unique(recorded_by,client_token),
 check(course_id is null or scope in ('learning','teaching')),
 check(unit<>'percent' or actual<=100 and (target is null or target<=100)),
 check(unit<>'count' or actual=trunc(actual) and (target is null or target=trunc(target)))
);
create index if not exists space_manual_metrics_scope_date on public.space_manual_metrics(scope,course_id,observed_on desc,created_at desc,id);
create index if not exists space_manual_metrics_owner_date on public.space_manual_metrics(owner_id,observed_on desc);
alter table public.space_manual_metrics enable row level security;
revoke all on public.space_manual_metrics from public,anon,authenticated;
grant select on public.space_manual_metrics to authenticated;
drop policy if exists manual_metrics_read on public.space_manual_metrics;
create policy manual_metrics_read on public.space_manual_metrics for select to authenticated using(
 public.is_approved() and (public.is_admin() or
  owner_id=(select auth.uid()) and scope='teaching' and public.is_teacher() and exists(
   select 1 from public.courses c where c.id=course_id and c.instructor_id=(select auth.uid())
  ))
);
create or replace function public.space_manual_metrics_immutable() returns trigger
language plpgsql set search_path='' as $$ begin raise exception 'Manual metric history is append-only; record a correction'; end $$;
revoke all on function public.space_manual_metrics_immutable() from public,anon,authenticated;
drop trigger if exists space_manual_metrics_immutable on public.space_manual_metrics;
create trigger space_manual_metrics_immutable before update or delete on public.space_manual_metrics
 for each row execute function public.space_manual_metrics_immutable();

create or replace function public.space_manual_metric_save(p_scope text,p_course uuid,p_label text,p_unit text,p_actual numeric,p_target numeric,p_observed date,p_source text,p_note text,p_token uuid,p_previous uuid default null)
returns uuid language plpgsql security definer set search_path='' as $save$
declare v_actor uuid:=auth.uid();v_admin boolean;v_id uuid:=gen_random_uuid();v_owner uuid;v_root uuid;v_revision integer:=1;v_old public.space_manual_metrics%rowtype;v_fingerprint text;v_existing public.space_manual_metrics%rowtype;
begin
 select role='admin' into v_admin from public.profiles where id=v_actor and membership_status='approved' and role in ('member','teacher','founder','admin') for share;
 if v_actor is null or v_admin is null then raise exception 'Approved editor access required' using errcode='42501'; end if;
 if p_scope is null or p_scope not in ('membership','learning','teaching','inventory','finance','orders') then raise exception 'Choose a manual metric scope';end if;
 if p_course is not null and p_scope not in ('learning','teaching') then raise exception 'Course does not belong to this scope';end if;
 if not v_admin and not(p_scope='teaching' and public.is_teacher() and p_course is not null) then raise exception 'Administrator or assigned teacher access required' using errcode='42501';end if;
 if p_course is not null then
  perform 1 from public.courses where id=p_course and (v_admin or instructor_id=v_actor) for share;
  if not found then raise exception 'Workshop unavailable' using errcode='42501';end if;
 end if;
 if p_token is null or p_label is null or length(trim(p_label)) not between 3 and 100 or p_source is null or length(trim(p_source)) not between 3 and 160 or length(coalesce(p_note,''))>1000 then raise exception 'Enter a label, source and valid note';end if;
 if p_unit is null or p_unit not in ('count','hours','percent','GHS') or p_actual is null or p_actual::text in ('NaN','Infinity','-Infinity') or p_actual<0 or p_actual>100000000000 or p_actual<>trunc(p_actual,2)
  or p_target is not null and (p_target::text in ('NaN','Infinity','-Infinity') or p_target<=0 or p_target>100000000000 or p_target<>trunc(p_target,2)) then raise exception 'Enter a nonnegative actual and positive optional target, with at most two decimals';end if;
 if p_unit='count' and (p_actual<>trunc(p_actual) or p_target is not null and p_target<>trunc(p_target)) or p_unit='percent' and (p_actual>100 or p_target>100) then raise exception 'Counts must be whole numbers; percentages cannot exceed 100';end if;
 if p_observed is null or p_observed<date '2000-01-01' or p_observed>(now() at time zone 'UTC')::date then raise exception 'Choose an observation date up to today';end if;
 v_fingerprint:=md5(jsonb_build_array(p_scope,p_course,trim(p_label),p_unit,p_actual,p_target,p_observed,trim(p_source),coalesce(trim(p_note),''),p_previous)::text);
 -- Serialize retries even before a first row exists. No external side effects.
 perform pg_advisory_xact_lock(hashtextextended(v_actor::text||p_token::text,0));
 select * into v_existing from public.space_manual_metrics where recorded_by=v_actor and client_token=p_token;
 if found then
  if v_existing.request_fingerprint<>v_fingerprint then raise exception 'This save token belongs to a different entry';end if;
  return v_existing.id;
 end if;
 v_owner:=v_actor;v_root:=v_id;
 if p_previous is not null then
  select * into v_old from public.space_manual_metrics where id=p_previous for update;
  if not found or not(v_admin or v_old.owner_id=v_actor and v_old.scope='teaching' and v_old.course_id=p_course)
   or v_old.scope<>p_scope or v_old.course_id is distinct from p_course then raise exception 'Entry unavailable' using errcode='42501';end if;
  if exists(select 1 from public.space_manual_metrics where supersedes_id=p_previous) then raise exception 'This entry was corrected already. Reload its latest version.';end if;
  if v_old.unit<>p_unit then raise exception 'Keep the original unit when correcting; use a new entry for a different measure';end if;
  v_owner:=v_old.owner_id;v_root:=v_old.root_id;v_revision:=v_old.revision+1;
 end if;
 insert into public.space_manual_metrics(id,root_id,revision,supersedes_id,owner_id,recorded_by,scope,course_id,label,unit,actual,target,observed_on,source,note,client_token,request_fingerprint)
 values(v_id,v_root,v_revision,p_previous,v_owner,v_actor,p_scope,p_course,trim(p_label),p_unit,p_actual,p_target,p_observed,trim(p_source),coalesce(trim(p_note),''),p_token,v_fingerprint);
 return v_id;
end;
$save$;
revoke all on function public.space_manual_metric_save(text,uuid,text,text,numeric,numeric,date,text,text,uuid,uuid) from public,anon;
grant execute on function public.space_manual_metric_save(text,uuid,text,text,numeric,numeric,date,text,text,uuid,uuid) to authenticated;

create or replace function public.space_manual_metric_list(p_scope text,p_days integer default 30,p_course uuid default null,p_offset integer default 0,p_root uuid default null)
returns jsonb language plpgsql stable security invoker set search_path='' as $list$
declare v_first date;v_count bigint;v_rows jsonb;
begin
 if not(public.is_admin() or public.is_teacher()) or not public.is_approved() then raise exception 'Editor access required' using errcode='42501';end if;
 if p_scope is null or p_scope not in ('membership','learning','teaching','inventory','finance','orders') or p_days is null or p_days not in (7,30,90) or p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'Invalid manual metrics view';end if;
 if not public.is_admin() and p_scope<>'teaching' then raise exception 'Teacher workshop access required' using errcode='42501';end if;
 v_first:=(now() at time zone 'UTC')::date-(p_days-1);
 with visible as materialized(
  select m.* from public.space_manual_metrics m where scope=p_scope and (p_course is null or course_id=p_course) and
   (p_root is not null and root_id=p_root or p_root is null and observed_on>=v_first and observed_on<=(now() at time zone 'UTC')::date and not exists(select 1 from public.space_manual_metrics newer where newer.supersedes_id=m.id))
 ), batch as(select * from visible order by created_at desc,id desc offset p_offset limit 20)
 select (select count(*) from visible),coalesce((select jsonb_agg(jsonb_build_object(
   'id',b.id,'root_id',b.root_id,'revision',b.revision,'course_id',b.course_id,'course_title',(select c.title from public.courses c where c.id=b.course_id),
   'label',b.label,'unit',b.unit,'actual',b.actual,'target',b.target,'observed_on',b.observed_on,'source',b.source,'note',b.note,'created_at',b.created_at,
   'is_mine',b.recorded_by=auth.uid()) order by b.created_at desc,b.id desc) from batch b),'[]'::jsonb)
 into v_count,v_rows;
 return jsonb_build_object('entries',v_rows,'total',v_count,'offset',p_offset,'history',p_root is not null);
end;
$list$;
revoke all on function public.space_manual_metric_list(text,integer,uuid,integer,uuid) from public,anon;
grant execute on function public.space_manual_metric_list(text,integer,uuid,integer,uuid) to authenticated;
commit;

-- LEGACY SOURCE: upgrade_analytics_periods.sql
-- SPACE administrator analytics. Run the whole file in Supabase SQL Editor.
-- Uses existing profile/finance RLS; does not grant access to private application answers.
begin;

create or replace function public.space_admin_analytics(
  p_scope text, p_from date, p_through date, p_grain text default 'day',
  p_status text default 'approved'
) returns jsonb language plpgsql stable security invoker set search_path = '' as $$
declare
  v_today date := (now() at time zone 'UTC')::date;
  v_rows jsonb; v_summary jsonb; v_step interval;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_scope is null or p_scope not in ('membership','finance') then raise exception 'Unknown analytics scope'; end if;
  if p_grain is null or p_grain not in ('day','month','year') then raise exception 'Choose day, month or year'; end if;
  if p_status is null or p_status not in ('approved','all') then raise exception 'Choose approved or all accounts'; end if;
  if p_from is null or p_through is null or p_from < date '2000-01-01' or p_through > v_today
     or p_from > p_through or p_through >= (p_from + interval '10 years')::date then
    raise exception 'Choose a valid period of less than 10 years, ending no later than today (UTC)';
  end if;
  if p_grain = 'day' and p_through-p_from > 365 then raise exception 'Daily grouping allows up to 366 days. Choose month or year for a longer period'; end if;
  v_step := case p_grain when 'day' then interval '1 day' when 'month' then interval '1 month' else interval '1 year' end;
  if p_scope = 'membership' then
    with buckets as (
      select d::date as period_start, greatest(d::date,p_from) as period_from,
        least((d+v_step-interval '1 day')::date,p_through) as period_through
      from pg_catalog.generate_series(pg_catalog.date_trunc(p_grain,p_from::timestamp),pg_catalog.date_trunc(p_grain,p_through::timestamp),v_step) d
    ), counts as (
      select pg_catalog.date_trunc(p_grain,p.created_at at time zone 'UTC')::date as period_start,
        count(*) filter(where p.role='member') as member,
        count(*) filter(where p.role='teacher') as teacher,
        count(*) filter(where p.role='founder') as founder,
        count(*) filter(where p.role='investor') as investor,
        count(*) filter(where p.role='admin') as admin
      from public.profiles p where p.created_at >= p_from::timestamp at time zone 'UTC'
        and p.created_at < (p_through+1)::timestamp at time zone 'UTC' and p.created_at<=now()
        and (p_status='all' or p.membership_status='approved') group by 1
    ) select coalesce(jsonb_agg(jsonb_build_object('date',b.period_start,'from',b.period_from,'through',b.period_through,
      'member',coalesce(c.member,0),'teacher',coalesce(c.teacher,0),'founder',coalesce(c.founder,0),
      'investor',coalesce(c.investor,0),'admin',coalesce(c.admin,0)) order by b.period_start),'[]'::jsonb)
      into v_rows from buckets b left join counts c using(period_start);
    select jsonb_build_object('accounts',count(*),'approved',count(*) filter(where membership_status='approved'),
      'pending',count(*) filter(where membership_status='pending')) into v_summary
      from public.profiles p where p.created_at >= p_from::timestamp at time zone 'UTC'
        and p.created_at < (p_through+1)::timestamp at time zone 'UTC' and p.created_at<=now()
        and (p_status='all' or p.membership_status='approved');
  else
    with buckets as (
      select d::date as period_start,greatest(d::date,p_from) as period_from,
        least((d+v_step-interval '1 day')::date,p_through) as period_through
      from pg_catalog.generate_series(pg_catalog.date_trunc(p_grain,p_from::timestamp),pg_catalog.date_trunc(p_grain,p_through::timestamp),v_step) d
    ), amounts as (
      select pg_catalog.date_trunc(p_grain,e.occurred_on::timestamp)::date as period_start,
        sum(e.amount) filter(where e.entry_type='income') as income,
        sum(e.amount) filter(where e.entry_type='expense') as expense
      from public.finance_entries e join public.finance_reviews r on r.entry_id=e.id and r.decision='approved'
      where e.occurred_on between p_from and p_through group by 1
    ) select coalesce(jsonb_agg(jsonb_build_object('date',b.period_start,'from',b.period_from,'through',b.period_through,
      'income',coalesce(a.income,0),'expense',coalesce(a.expense,0)) order by b.period_start),'[]'::jsonb)
      into v_rows from buckets b left join amounts a using(period_start);
    select jsonb_build_object(
      'income',coalesce(sum(e.amount) filter(where e.entry_type='income' and e.occurred_on>=p_from),0),
      'expense',coalesce(sum(e.amount) filter(where e.entry_type='expense' and e.occurred_on>=p_from),0),
      'transactions',count(*) filter(where e.occurred_on>=p_from),
      'opening',coalesce(sum(case when e.entry_type='income' then e.amount else -e.amount end) filter(where e.occurred_on<p_from),0),
      'closing',coalesce(sum(case when e.entry_type='income' then e.amount else -e.amount end),0))
      into v_summary from public.finance_entries e join public.finance_reviews r on r.entry_id=e.id and r.decision='approved'
      where e.occurred_on<=p_through;
  end if;
  return jsonb_build_object('scope',p_scope,'from',p_from,'through',p_through,'grain',p_grain,'status',p_status,
    'timezone','UTC','generated_at',now(),'rows',v_rows,'summary',v_summary);
end;
$$;
revoke all on function public.space_admin_analytics(text,date,date,text,text) from public,anon;
grant execute on function public.space_admin_analytics(text,date,date,text,text) to authenticated;

-- Keyset-paginated member export. One JSON result per request avoids API row caps.
-- as_of fixes the creation cutoff, not subsequent role/status/name edits.
create or replace function public.space_analytics_members(
  p_from date, p_through date, p_status text default 'approved',
  p_after_created timestamptz default null, p_after_id uuid default null,
  p_as_of timestamptz default null, p_limit integer default 500
) returns jsonb language plpgsql stable security invoker set search_path = '' as $$
declare
  v_cutoff timestamptz := least(coalesce(p_as_of,now()),now());
  v_rows jsonb; v_total bigint; v_more boolean; v_last jsonb;
begin
  if not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_from is null or p_through is null or p_from < date '2000-01-01'
    or p_through > (now() at time zone 'UTC')::date or p_from>p_through
    or p_through >= (p_from+interval '10 years')::date then raise exception 'Choose a valid export period'; end if;
  if p_status is null or p_status not in ('approved','all') then raise exception 'Choose approved or all accounts'; end if;
  if p_limit is null or p_limit<1 or p_limit>500 then raise exception 'Export page size must be 1 to 500'; end if;
  if (p_after_created is null) <> (p_after_id is null) then raise exception 'Both export cursor values are required'; end if;
  select count(*) into v_total from public.profiles p where p.created_at>=p_from::timestamp at time zone 'UTC'
    and p.created_at<(p_through+1)::timestamp at time zone 'UTC' and p.created_at<=v_cutoff
    and (p_status='all' or p.membership_status='approved');
  with candidates as (
    select p.id,p.full_name,p.handle,p.role,p.membership_status,p.created_at
    from public.profiles p where p.created_at>=p_from::timestamp at time zone 'UTC'
      and p.created_at<(p_through+1)::timestamp at time zone 'UTC' and p.created_at<=v_cutoff
      and (p_status='all' or p.membership_status='approved')
      and (p_after_created is null or (p.created_at,p.id)>(p_after_created,p_after_id))
    order by p.created_at,p.id limit p_limit+1
  ), numbered as (select *,row_number() over(order by created_at,id) as n from candidates)
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'full_name',full_name,'handle',handle,
    'role',role,'membership_status',membership_status,'created_at',created_at) order by created_at,id) filter(where n<=p_limit),'[]'::jsonb),
    coalesce(bool_or(n>p_limit),false) into v_rows,v_more from numbered;
  v_last := v_rows->(jsonb_array_length(v_rows)-1);
  return jsonb_build_object('rows',v_rows,'total',v_total,'more',v_more,'as_of',v_cutoff,
    'next_created',case when v_more then v_last->>'created_at' else null end,
    'next_id',case when v_more then v_last->>'id' else null end);
end;
$$;
revoke all on function public.space_analytics_members(date,date,text,timestamptz,uuid,timestamptz,integer) from public,anon;
grant execute on function public.space_analytics_members(date,date,text,timestamptz,uuid,timestamptz,integer) to authenticated;
create index if not exists space_analytics_profile_cursor on public.profiles(created_at,id);
create index if not exists space_analytics_finance_date on public.finance_entries(occurred_on,id);
commit;

-- LEGACY SOURCE: upgrade_guidance_system_health.sql
-- Run after the existing SPACE course, membership and notification upgrades.
-- Additive/rerunnable. No application records, jobs, files or secrets are removed.
begin;

create table if not exists public.space_client_issue_reports (
  user_id uuid not null references public.profiles(id) on delete cascade,
  category text not null check(category in ('upload','notifications')),
  code text not null check(code in ('network','permission','configuration','unavailable','unknown')),
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  reviewed_at timestamptz,
  reviewed_by uuid references public.profiles(id) on delete set null,
  primary key(user_id,category)
);
create index if not exists space_client_issue_unreviewed on public.space_client_issue_reports(category,last_seen_at) where reviewed_at is null;
alter table public.space_client_issue_reports enable row level security;
revoke all on public.space_client_issue_reports from public,anon,authenticated;

-- Store fixed categories only: never filenames, message text, email addresses,
-- push endpoints, credentials, raw errors or document paths. At most two rows
-- per account, with repeated reports suppressed for one minute.
create or replace function public.space_report_client_issue(p_category text,p_code text)
returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not public.is_approved() then raise exception 'Approved account required';end if;
 if p_category not in ('upload','notifications') or p_category is null
    or p_code not in ('network','permission','configuration','unavailable','unknown') or p_code is null then raise exception 'Invalid issue category';end if;
 insert into public.space_client_issue_reports(user_id,category,code)
 values(auth.uid(),p_category,p_code)
 on conflict(user_id,category) do update set code=excluded.code,last_seen_at=now(),reviewed_at=null,reviewed_by=null
 where space_client_issue_reports.last_seen_at<now()-interval '1 minute' or space_client_issue_reports.reviewed_at is not null;
end $$;
revoke all on function public.space_report_client_issue(text,text) from public,anon;
grant execute on function public.space_report_client_issue(text,text) to authenticated;

create or replace function public.space_admin_review_client_issues(p_category text,p_before timestamptz)
returns integer language plpgsql security definer set search_path='' as $$
declare v_count integer;
begin
 if not public.is_admin() then raise exception 'Administrator access required';end if;
 if p_category is null or p_category not in ('upload','notifications') or p_before is null or p_before>now()+interval '5 seconds' then raise exception 'Invalid review boundary';end if;
 update public.space_client_issue_reports set reviewed_at=now(),reviewed_by=auth.uid()
 where category=p_category and reviewed_at is null and last_seen_at<=p_before;
 get diagnostics v_count=row_count;return v_count;
end $$;
revoke all on function public.space_admin_review_client_issues(text,timestamptz) from public,anon;
grant execute on function public.space_admin_review_client_issues(text,timestamptz) to authenticated;

-- Own-account checklist facts. Missing optional migrations return JSON null,
-- so an unavailable check is never presented as a completed task.
create or replace function public.space_onboarding_status()
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_id uuid:=auth.uid();v_role text;v_teacher boolean;v_result jsonb;v_done boolean;
begin
 if v_id is null or not public.is_approved() then raise exception 'Approved account required';end if;
 select role into v_role from public.profiles where id=v_id;
 v_teacher:=public.is_teacher();
 v_result:=jsonb_build_object('tracks',null,'enrolled',null,'first_post',null,'teaching_profile',null,'signature',null,'published_course',null,'materials',null,'assignment',null);
 if to_regclass('public.member_learning_paths') is not null then
  execute 'select exists(select 1 from public.member_learning_paths where user_id=$1 and cardinality(tracks)>0)' into v_done using v_id;
  v_result:=v_result||jsonb_build_object('tracks',v_done);
 end if;
 if to_regclass('public.course_enrollments') is not null then
  execute 'select exists(select 1 from public.course_enrollments where learner_id=$1)' into v_done using v_id;
  v_result:=v_result||jsonb_build_object('enrolled',v_done);
 end if;
 if to_regclass('public.activity_posts') is not null and v_role<>'investor' then
  execute 'select exists(select 1 from public.activity_posts p where author_id=$1 and to_jsonb(p)->>''deleted_at'' is null)' into v_done using v_id;
  v_result:=v_result||jsonb_build_object('first_post',v_done);
 end if;
 if v_teacher then
  if to_regclass('public.teacher_profiles') is not null then
   execute 'select exists(select 1 from public.teacher_profiles where teacher_id=$1)' into v_done using v_id;
   v_result:=v_result||jsonb_build_object('teaching_profile',v_done);
  end if;
  if to_regclass('public.space_certificate_signatories') is not null then
   execute 'select exists(select 1 from public.space_certificate_signatories where user_id=$1 and consent_at is not null)' into v_done using v_id;
   v_result:=v_result||jsonb_build_object('signature',v_done);
  end if;
  if to_regclass('public.courses') is not null then
   execute 'select exists(select 1 from public.courses c where instructor_id=$1 and coalesce(to_jsonb(c)->>''status'',''open'')<>''archived'')' into v_done using v_id;
   v_result:=v_result||jsonb_build_object('published_course',v_done);
  end if;
  if to_regclass('public.learning_materials') is not null then
   execute 'select exists(select 1 from public.learning_materials m join public.courses c on c.id=m.course_id where c.instructor_id=$1 and m.uploaded_by=$1 and to_jsonb(m)->>''hidden_at'' is null)' into v_done using v_id;
   v_result:=v_result||jsonb_build_object('materials',v_done);
  end if;
  if to_regclass('public.classroom_assignments') is not null then
   execute 'select exists(select 1 from public.classroom_assignments a join public.courses c on c.id=a.course_id where c.instructor_id=$1)' into v_done using v_id;
   v_result:=v_result||jsonb_build_object('assignment',v_done);
  end if;
 end if;
 return v_result;
end $$;
revoke all on function public.space_onboarding_status() from public,anon;
grant execute on function public.space_onboarding_status() to authenticated;

-- Aggregate delivery status only. No recipient identities, endpoint URLs,
-- VAPID/SMTP secrets or raw provider messages leave this function.
create or replace function public.space_admin_system_health()
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_checks jsonb:='[]';v_email jsonb;v_push jsonb;v_uploads jsonb;v_notices jsonb;
 v_name text;v_present boolean;v_count integer;v_active integer;v_jobs jsonb;v_storage jsonb;v_security boolean;
begin
 if not public.is_admin() then raise exception 'Administrator access required';end if;
 foreach v_name in array array['course_enrollments','classroom_assignments','space_course_lessons','space_class_sessions','space_certificates','space_certificate_signatories','application_answers'] loop
  v_present:=to_regclass('public.'||v_name) is not null;
  v_checks:=v_checks||jsonb_build_array(jsonb_build_object('key',v_name,'present',v_present));
 end loop;
 if to_regclass('public.approval_email_outbox') is not null then
  execute $q$select jsonb_build_object('pending',count(*) filter(where status in ('pending','retry')),'processing',count(*) filter(where status='processing'),'failed',count(*) filter(where status='failed'),'overdue',count(*) filter(where (status in ('pending','retry') and next_attempt_at<now()-interval '10 minutes') or (status='processing' and locked_at<now()-interval '10 minutes')),'sent_24h',count(*) filter(where status='sent' and sent_at>now()-interval '24 hours'),'last_sent_at',max(sent_at)) from public.approval_email_outbox$q$ into v_email;
 end if;
 if to_regclass('public.push_outbox') is not null then
  execute $q$select jsonb_build_object('pending',count(*) filter(where status in ('pending','retry')),'processing',count(*) filter(where status='processing'),'failed_24h',count(*) filter(where status='failed' and created_at>now()-interval '24 hours'),'overdue',count(*) filter(where (status in ('pending','retry') and next_attempt_at<now()-interval '10 minutes') or (status='processing' and locked_at<now()-interval '10 minutes')),'sent_24h',count(*) filter(where status='sent' and sent_at>now()-interval '24 hours'),'last_sent_at',max(sent_at)) from public.push_outbox$q$ into v_push;
 end if;
 if to_regclass('public.push_subscriptions') is not null and v_push is not null then
  execute 'select count(*)::integer from public.push_subscriptions' into v_count;
  v_push:=coalesce(v_push,'{}')||jsonb_build_object('registered_devices',v_count);
 end if;
 select jsonb_build_object('affected_members',count(*),'last_report_at',max(last_seen_at)) into v_uploads from public.space_client_issue_reports where category='upload' and reviewed_at is null;
 select jsonb_build_object('affected_members',count(*),'last_report_at',max(last_seen_at)) into v_notices from public.space_client_issue_reports where category='notifications' and reviewed_at is null;
 v_jobs:=jsonb_build_object('cron_available',to_regclass('cron.job') is not null,'approval_job',null,'push_job',null);
 if to_regclass('cron.job') is not null then
  begin
   execute 'select count(*)::integer from cron.job where active and jobname=''innovatex-approval-email-worker''' into v_active;
   v_jobs:=v_jobs||jsonb_build_object('approval_job',v_active>0);
   execute 'select count(*)::integer from cron.job where active and (jobname ilike ''%push%worker%'' or jobname ilike ''%push%deliver%'')' into v_active;
   v_jobs:=v_jobs||jsonb_build_object('push_job',v_active>0);
  exception when insufficient_privilege or undefined_column then null;
  end;
 end if;
 if to_regclass('storage.buckets') is not null then
  execute $q$select coalesce(jsonb_agg(jsonb_build_object('name',x.name,'present',b.id is not null,'visibility_ok',case when b.id is null then null else coalesce(b.public,false)=(x.name='club-founder-portraits') end)),'[]') from unnest(array['club-media','club-documents','club-learning','club-course-evidence','club-finance-receipts','club-direct-files','club-shop-images','club-teacher-signatures','club-founder-portraits']) x(name) left join storage.buckets b on b.id=x.name$q$ into v_storage;
 end if;
 select not exists(select 1 from information_schema.columns where table_schema='public' and table_name='profiles' and column_name='application_reason') and to_regclass('public.application_answers') is not null into v_security;
 return jsonb_build_object('checked_at',now(),'schema_checks',v_checks,'application_privacy_migration',v_security,'approval_emails',v_email,'push',v_push,'upload_reports',v_uploads,'notification_reports',v_notices,'schedules',v_jobs,'storage',v_storage);
end $$;
revoke all on function public.space_admin_system_health() from public,anon;
grant execute on function public.space_admin_system_health() to authenticated;

notify pgrst,'reload schema';
commit;
